import CmuxNextCompat
public import CoreGraphics
public import Foundation

/// The cmux icon pack (Resources/cmux-icons.json, generated by
/// scripts/icons/build_pack.py): every icon's drawings on a square grid.
public nonisolated struct IconPack: Sendable, Decodable {
    public var id: String
    public var version: Int
    /// Side of the drawing grid in units (24).
    public var grid: CGFloat
    public var icons: [String: IconDrawing]

    public init(id: String = "cmux", version: Int = 1, grid: CGFloat = 24, icons: [String: IconDrawing]) {
        self.id = id
        self.version = version
        self.grid = grid
        self.icons = icons
    }

    public init(data: Data) throws {
        self = try JSONDecoder().blockingDecode(IconPack.self, from: data)
    }

    /// The pack shipped in this module's bundle, with the family overlay (``useOverlay(_:)``) laid
    /// over it; empty when the bundle is missing or unreadable, so every icon falls back to SF Symbols.
    public static var bundled: IconPack { overlayName.withLock { $0 } == nil ? shipped : overlaid }

    /// Debug Settings `icons.family` (the App sets it at launch, before the first icon draws):
    /// nil draws the shipped pack; a name lays `cmux-icons-<name>.json` over it.
    public static func useOverlay(_ name: String?) {
        overlayName.withLock { $0 = name }
    }

    /// Decodes the shipped pack and ``IconCatalog/bundled`` on a new one-shot thread, then calls
    /// `decoded` there: 367 KB of JSON in two `swift_once`s that the first tab, sidebar row or menu
    /// icon otherwise decodes on the main thread before the first frame. The launch calls it from
    /// `main()`; a draw that comes first waits only for the rest of that one decode. The Debug
    /// overlay is left alone: Debug Settings chooses it later, on main.
    public static func decodeBundledInBackground(then decoded: @escaping @Sendable () -> Void) {
        decodeInBackground({ _ = shipped; _ = IconCatalog.bundled }, then: decoded)
    }

    /// The warm-up thread of ``decodeBundledInBackground(then:)``: runs `decode`, then `decoded`, on it.
    package static func decodeInBackground(
        _ decode: @escaping @Sendable () -> Void,
        then decoded: @escaping @Sendable () -> Void
    ) {
        let thread = Thread {
            decode()
            decoded()
        }
        thread.name = "cmux-next icon warm-up"
        thread.qualityOfService = .userInitiated
        thread.start()
    }

    private static let overlayName = Mutex<String?>(nil)
    private static let shipped: IconPack = load("cmux-icons") ?? IconPack(icons: [:])
    private static let overlaid: IconPack = {
        guard let name = overlayName.withLock({ $0 }), let overlay = load("cmux-icons-\(name)") else { return shipped }
        var pack = shipped
        pack.icons.merge(overlay.icons) { _, drawn in drawn }
        return pack
    }()

    private static func load(_ resource: String) -> IconPack? {
        guard let data = IconResources.json(named: resource) else { return nil }
        do {
            return try IconPack(data: data)
        } catch {
            IconResources.logger.error("\(resource, privacy: .public).json did not decode: \(String(describing: error), privacy: .public)")
            return nil
        }
    }

    public func drawing(for name: IconName) -> IconDrawing? {
        icons[name.rawValue]
    }
}
